def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None

    # The separator divides the grid into two equal-sized panels.
    for r in range(1, h - 1):
        if h - r - 1 == r and len(set(grid[r])) == 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(1, w - 1):
            if w - c - 1 == c and len({grid[r][c] for r in range(h)}) == 1:
                split = ("col", c)
                break

    if split[0] == "row":
        s = split[1]
        a, b = grid[:s], grid[s + 1:]
    else:
        s = split[1]
        a = [row[:s] for row in grid]
        b = [row[s + 1:] for row in grid]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    fill = next(iter(shared))
    return [[3 if a[r][c] == b[r][c] else fill
             for c in range(len(a[0]))] for r in range(len(a))]
